import type { Chapter } from '../../types'

// M9 fact bank. Distilled from the official M9 study text and chapter notes.
// Chapters 1-4 are authored in depth; 5-17 carry solid seed concepts and grow over time.
export const m9Chapters: Chapter[] = [
  {
    id: 'ch1',
    num: 1,
    title: 'Risk And Life Insurance',
    page: 1,
    concepts: [
      { id: 'c1-01', term: 'Speculative vs pure risk', fact: 'Speculative risk has three outcomes (gain, loss, no change), e.g. buying a stock. Pure risk has only two (loss or no loss), no upside. Only pure risk is insurable, because insurance compensates a loss, not hands a profit.', trap: 'Only pure risk is insurable; speculative risk (stocks, gambling) is not.' },
      { id: 'c1-02', term: 'Requirements for an insurable risk', fact: 'The loss must be significant, occur by chance, be definite, be calculable, and not be catastrophic to the insurer; plus there must be a large number of similar exposure units (law of large numbers).', trap: 'A catastrophic risk that could bankrupt the insurer (e.g. nuclear) is NOT insurable.' },
      { id: 'c1-03', term: 'Four ways of dealing with risk', fact: 'Avoid, Control, Retain (self-insure), Transfer. Insurance is a risk-transfer mechanism.', trap: 'Retain and self-insure mean the same thing.' },
      { id: 'c1-04', term: 'Three personal risks life insurance addresses', fact: 'Premature death, outliving your resources (longevity risk), and poor health/disablement.' },
      { id: 'c1-05', term: 'Policy owner vs life insured', fact: 'The policy owner owns the policy; the life insured is the person whose life is covered. A third-party policy is where one person insures another person\u2019s life.', trap: 'Owner and life insured can be different people; this is a classic exam trap.' },
      { id: 'c1-06', term: 'Sum assured', fact: 'The guaranteed lump sum paid on a claim (face amount / face value), shown on the first page of the policy.' },
      { id: 'c1-07', term: 'Insurance vs gambling', fact: 'Gambling creates new speculative risk and is zero-sum. Insurance handles an existing pure risk, creates nothing new, and is mutually beneficial and socially productive.', trap: 'Gambling creates risk; insurance transfers existing risk.' },
      { id: 'c1-08', term: 'Physical vs moral hazard', fact: 'Physical hazard is a physical characteristic raising the chance of loss (obesity, heart history). Moral hazard is dishonest behaviour around insurance (over-insuring, lying on the form).', trap: 'A hazard increases the likelihood of loss; don\u2019t confuse it with a peril (the cause) or the risk itself.' },
      { id: 'c1-09', term: 'Anti-selection (adverse selection)', fact: 'The tendency for higher-risk people to seek cover more eagerly, worsening the pool. The main defence is underwriting, which classifies applicants as standard, sub-standard, or declined/postponed.' },
      { id: 'c1-10', term: 'Pooling of risk & law of large numbers', fact: 'Many pay premiums into a pool; the few who suffer losses are paid from it. The law of large numbers says more insured lives make actual losses track expected losses closely. This is the mathematical foundation of insurance.' },
      { id: 'c1-11', term: 'Utmost good faith (uberrima fides)', fact: 'The proposer must disclose all material facts they know or ought to know, even if the form doesn\u2019t ask. Material facts change how an underwriter handles the case. The duty runs to inception and revives on alteration.', trap: 'For a life policy the duty does NOT revive on renewal (a life policy isn\u2019t renewed annually); contrast general insurance.' },
      { id: 'c1-12', term: 'Insurable interest (life)', fact: 'You have it if you benefit from the insured living and lose if they die. Under s57 Insurance Act, for life insurance the interest must exist at inception but NOT at time of death.', trap: 'Life: inception only. General: inception AND time of loss. Marine cargo: time of loss only.' },
      { id: 'c1-13', term: 'Recognised insurable interest (life)', fact: 'Your own life; your spouse (if married when effected); your child/ward under 18; a person you are wholly or partly dependent on. Also creditor-debtor, key-person, and trustees/beneficiaries.' },
      { id: 'c1-14', term: 'Principle of indemnity', fact: 'Restores you to your pre-loss financial position with no profit. It applies to general and health insurance but NOT to life or personal accident, which are benefit policies with an agreed sum assured.', trap: 'Life and personal accident insurance are NOT contracts of indemnity.' },
      { id: 'c1-15', term: 'Singapore market supporting bodies', fact: 'MAS (regulator), LIA (market association), FIDReC (dispute resolution: filing \u2192 mediation \u2192 adjudication), rating agencies, MoneySENSE, and SDIC (deposit and policy owner protection).' },
    ],
  },
  {
    id: 'ch2',
    num: 2,
    title: 'Setting Life Insurance Premium',
    page: 29,
    concepts: [
      { id: 'c2-01', term: 'Who sets premiums & the balancing act', fact: 'Actuaries set premiums, balancing three things: covering expected claims, covering expenses plus a profit margin, yet staying competitive with other insurers.' },
      { id: 'c2-02', term: 'Mortality & morbidity rates', fact: 'Mortality rate is the probability of death at each age, compiled into a mortality table using the law of large numbers. Morbidity is the rate of sickness/injury, the main input for health insurance.', trap: 'Morbidity is for health insurance; mortality for life. Health pricing still also considers mortality.' },
      { id: 'c2-03', term: 'Investment income in pricing', fact: 'Insurers invest the early-year surplus from level premiums; expected returns are used to reduce the premium. A higher assumed interest rate means a lower premium.' },
      { id: 'c2-04', term: 'Net, loading, and gross premium', fact: 'Net premium covers protection only (mortality/morbidity + investment income). Loading covers expenses plus profit. Gross premium = net + loading, and is what the proposer actually pays.', trap: 'Net + loading = gross.' },
      { id: 'c2-05', term: 'Gender in pricing', fact: 'For life insurance, female premiums are generally lower (women live longer) via the reduction-in-age method. For health insurance, female premiums tend to be higher (more hospitalisation, especially above 65).', trap: 'The gender effect flips between life and health insurance.' },
      { id: 'c2-06', term: 'Smoking status', fact: 'Non-smokers receive discounts because they statistically enjoy better health and longer life.' },
      { id: 'c2-07', term: 'Amount of sum assured & volume discount', fact: 'Premiums are quoted per $1,000 of sum assured. Because some admin costs are fixed, large policies get a volume discount applied as a reduction to the per-$1,000 rate, not a flat rebate.' },
      { id: 'c2-08', term: 'Frequency of premium payment', fact: 'More frequent modes (monthly, quarterly) carry a small surcharge for lost interest and processing. A single premium is lower overall because the insurer gets the whole amount to invest upfront.' },
      { id: 'c2-09', term: 'Premium types', fact: 'Single; Recurrent single (each is its own single premium, can stop anytime and becomes paid-up); Regular; Yearly renewable (rises each year); Limited (paid over a set period, higher each premium).', trap: 'CPF monies can buy only single or recurrent single premium policies.' },
    ],
  },
  {
    id: 'ch3',
    num: 3,
    title: 'Classification Of Life Insurance Products',
    page: 37,
    concepts: [
      { id: 'c3-01', term: 'Four ways to classify life products', fact: 'By statutory fund, product type, premium type, and ownership. These are four independent lenses, not a hierarchy; a policy sits in all four at once.' },
      { id: 'c3-02', term: 'Classification by statutory insurance fund', fact: 'Under s17 Insurance Act, insurers keep separate funds. Three types: participating, non-participating, investment-linked. Par and non-par may share a fund, but the investment-linked fund must be separate.', trap: 'Only the investment-linked fund is mandatorily kept separate.' },
      { id: 'c3-03', term: 'Participating vs non-participating', fact: 'Par (with-profits) policies share in surplus via bonuses. Non-par (e.g. Term, Universal Life) get no bonus. Whole Life and Endowment come in both par and non-par forms.', trap: 'Whole Life and Endowment can be par OR non-par; don\u2019t pin them to one side.' },
      { id: 'c3-04', term: 'Classification by product type', fact: 'Term, Whole Life, Endowment, ILP, Universal Life, Annuities; plus health products: Critical Illness, Medical Expenses/H&S, Disability Income, Long-Term Care.' },
      { id: 'c3-05', term: 'Classification by ownership', fact: 'Single life (owner = insured, most common), Joint life (usually two lives), Third-party (cover can differ per party), and Group (many lives, e.g. an employer).' },
      { id: 'c3-06', term: 'Joint life: first-to-die vs last survivor', fact: 'First-to-die pays on the first death, the benefit goes to the survivor and cover ends (e.g. joint mortgage decreasing term). Last survivor/second-to-die pays only when both have died (uncommon in Singapore).' },
      { id: 'c3-07', term: 'Characteristics of group life insurance', fact: 'The group must exist for a purpose other than buying insurance. It runs under a master contract, with minimal underwriting (free cover limit), experience rating, cost effectiveness, and yearly renewal by the employer.', trap: 'You can\u2019t gather strangers just to buy group cover; the group must exist for another purpose.' },
      { id: 'c3-08', term: 'Group term life insurance', fact: 'The most sold group class in Singapore. Conceptually a Yearly Renewable Term, but the premium varies with the group\u2019s size and claims experience, not each individual\u2019s advancing age. Usually to age 65, with death and TPD benefits.' },
    ],
  },
  {
    id: 'ch4',
    num: 4,
    title: 'Traditional Life Insurance Products',
    page: 49,
    concepts: [
      { id: 'c4-01', term: 'Term insurance nature', fact: 'Cover for a fixed term; pays the sum assured only if the insured dies during the term. Temporary, no savings/investment. Issued non-par only, has no cash value, and carries the lowest premium.', trap: 'Survive the term and you get nothing; no cash value means no policy loan, APL, or non-forfeiture options.' },
      { id: 'c4-02', term: 'Three types of term', fact: 'Level term (benefit and premium level, e.g. key person). Decreasing term (benefit falls, e.g. mortgage decreasing term). Increasing term (benefit rises to counter inflation, uncommon in SG).' },
      { id: 'c4-03', term: 'Mortgage decreasing term', fact: 'The sum assured is designed to track the falling loan balance, but each year\u2019s figure is fixed at outset using assumed rates and repayments, so the actual payout may be more or less than the outstanding loan.', trap: 'The declining sum assured is fixed at outset, not recalculated to the real loan balance.' },
      { id: 'c4-04', term: 'Renewable option', fact: 'The right to renew at term-end without evidence of insurability, usually to a cut-off age. The premium rises to attained age, pushed up by anti-selection. YRT renews yearly and suits the young.', trap: 'The renewal premium rises because of anti-selection; don\u2019t advise older clients into YRT.' },
      { id: 'c4-05', term: 'Convertible option', fact: 'The right to convert term into a permanent policy without evidence of insurability. Attained-age conversion is priced at the conversion age (common); original-age conversion is priced at the original age but needs a lump sum and is time-limited.' },
      { id: 'c4-06', term: 'Whole life insurance nature', fact: 'Pays the face value (plus bonuses if par) on death whenever it occurs \u2014 lifetime protection. \u201CWhole life\u201D refers to the duration of protection, not the premium-paying period. It has cash value and can be par or non-par.', trap: '\u201CWhole life\u201D means coverage duration, not how long you pay (Ordinary vs Limited Payment Whole Life).' },
      { id: 'c4-07', term: 'Cash value (why term has none)', fact: 'Cash value arises from charging level premiums for a certain event (death is guaranteed eventually). Term covers an uncertain event over a term, so it has none. At around age 100 the cash value equals the sum assured and the policy matures.' },
      { id: 'c4-08', term: 'Non-forfeiture options', fact: 'Uses of accumulated cash value if you stop paying: (1) Surrender for net cash value; (2) Reduced paid-up insurance; (3) Extended Term Insurance (ETI). ETI is the automatic default if nothing is elected.', trap: 'ETI is the default. Net cash value = cash value \u2212 loans/interest + bonus accumulations.' },
      { id: 'c4-09', term: 'Endowment insurance nature', fact: 'Pays the death benefit if the insured dies during the term, or an equal maturity value on survival. Its defining feature is a fixed maturity date. It carries the highest premium of the three (heavy savings element).', trap: 'Think of endowment as a whole life with the survivorship payout brought forward to a fixed maturity date.' },
      { id: 'c4-10', term: 'Types of endowment', fact: 'Pure endowment pays only on survival, nothing on death (mirror of term, not sold standalone). Anticipated (\u201Cmoney-back\u201D) endowment pays a percentage at intervals; the death benefit is NOT reduced by cash payments already received.' },
      { id: 'c4-11', term: 'Term vs Whole Life vs Endowment', fact: 'Premium: Term lowest, WL middle, Endowment highest. Cash value: Term none, WL builds slowly, Endowment builds quickly. Pays on survival: Term no, WL yes (~age 100), Endowment yes (at maturity).' },
      { id: 'c4-12', term: 'Point-of-sale disclosure (life)', fact: 'Under MAS Notice FAA-N16, give the Cover Page, Product Summary, Policy Illustration, Bundled Product Disclosure Document, and (ILPs only) Product Highlights Sheet. LIA requires \u201CYour Guide To Life Insurance Policies\u201D. Guideline ID01/17 governs no-advice online sales.' },
    ],
  },
  {
    id: 'ch5',
    num: 5,
    title: 'Riders (Or Supplementary Benefits)',
    page: 83,
    concepts: [
      { id: 'c5-01', term: 'What a rider is', fact: 'A supplementary benefit that attaches to a basic policy, adding cover the basic contract lacks. It must be requested and approved, costs an extra premium, and is shown in the policy schedule with an endorsement.' },
      { id: 'c5-02', term: 'General rules for riders', fact: 'You cannot buy a rider without a basic policy, nor cancel the basic policy while keeping the rider. A rider\u2019s term cannot exceed the basic policy\u2019s term. Riders have no cash value and automatically terminate when the basic policy converts to Extended Term Insurance (ETI).', trap: 'Riders carry no cash value and die when the policy goes to ETI; on a lapse the insurer may reinstate the basic policy but refuse the rider.' },
      { id: 'c5-03', term: 'Waiver of Premium (WoP) rider', fact: 'Waives future premiums when the life insured suffers TPD or a covered critical illness, keeping the policy in force and cash value growing. May be folded into the basic premium or bought separately (not on single-premium policies). Usually expires around age 60/65 with a six-month waiting period on the TPD version.', trap: 'Don\u2019t recommend WoP-on-CI if the basic cover already gives 100% acceleration of the death benefit on CI: the policy pays out and terminates, so there are no premiums left to waive.' },
      { id: 'c5-04', term: 'Total & Permanent Disability (TPD) rider', fact: 'Usually issued with WoP in one endorsement, sharing its waiting period and definition. Pays a lump sum or instalments (a % of sum assured over several years). Once instalments begin, all other riders terminate except an Extended TPD rider. Aggregate TPD is typically capped around $2m per insurer; nothing is paid for intentionally self-inflicted injury.' },
      { id: 'c5-05', term: 'Critical Illness rider: Acceleration vs Additional', fact: 'Acceleration (accelerator) pre-pays part or all of the BASIC sum assured, so it reduces the basic cover; 100% acceleration terminates the policy. Max payable = basic SA + bonuses. Additional Benefit pays ON TOP of the basic SA, leaving death cover intact; rider SA can be a multiple of the basic. Max payable = basic SA + bonuses + rider SA.', trap: 'Acceleration eats into the basic sum assured; Additional pays on top and leaves it intact.' },
      { id: 'c5-06', term: 'CI rider: waiting vs survival period', fact: 'Waiting period is 90 days (to defeat anti-selection) and applies to ALL CI riders. Survival period is usually 30 days after diagnosis and applies ONLY to the Additional Benefit. The 37 covered critical illnesses and their definitions are standardised across all insurers in Singapore.', trap: '90-day waiting period = all CI riders; 30-day survival period = Additional Benefit only.' },
      { id: 'c5-07', term: 'Term rider', fact: 'A term plan attached to a permanent policy, sized as a ratio to the basic SA (e.g. 3:1, 5:1). You cannot put a term rider on a term policy (raise the term SA instead). Level term boosts cover for a period; decreasing term is common for mortgage protection and is cheaper than a standalone decreasing term policy.', trap: 'A term rider only attaches to a PERMANENT policy, never to a term policy.' },
      { id: 'c5-08', term: 'Family Income Benefit rider', fact: 'A DECREASING term rider on a juvenile policy paying a regular income to a child. The earlier the payor dies, the more total income the child receives.', trap: 'Family Income Benefit is a decreasing rider, because fewer payments remain the later the death occurs.' },
      { id: 'c5-09', term: 'Payor Benefit rider', fact: 'On a juvenile (third-party) policy: if the payor (usually a parent) dies or becomes disabled before the child reaches a specified age (e.g. 21 or 25), premiums are waived until the child reaches that age. Some versions add CI to the triggering events.' },
      { id: 'c5-10', term: 'Guaranteed Insurability Option (GIO) rider', fact: 'Not a cover but a RIGHT to buy additional insurance at set intervals or life events (ages 30/35/40, or marriage/birth of a child) without evidence of insurability. Max additional cover is usually the original SA, priced at attained age. Skipping one option date does not forfeit the next. Especially valuable on juvenile policies.', trap: 'GIO is a right to buy future cover, not cover itself.' },
      { id: 'c5-11', term: 'Accidental Death Benefit (ADB) rider', fact: 'Pays an additional amount on accidental death, usually equal to the basic SA, hence \u201Cdouble indemnity\u201D. Expires around age 60. \u201CAccident\u201D must be caused by external, violent and visible means. Sold standalone by a general insurer, it becomes a Personal Accident policy.', trap: 'ADB = double indemnity; sold on its own it is Personal Accident insurance.' },
      { id: 'c5-12', term: 'Accidental Death & Dismemberment (AD&D) rider', fact: 'ADB plus cover for dismemberment (severance/amputation) or disablement (functional permanent loss) of limbs, sight, hearing or speech, paid as a percentage of the rider SA. Not strictly life insurance; suited to blue-collar and higher-risk occupations.' },
      { id: 'c5-13', term: 'Hospital Cash (Income) Benefit rider', fact: 'Pays a fixed daily benefit (e.g. $150/day) for hospital confinement regardless of actual charges. Subject to limits (e.g. 90 days per stay, a lifetime cap like 730x the daily benefit) and a waiting period (30/45 days). Because it pays from the first dollar, it is useful to cover the co-payment/deductible under a separate Medical Expense policy.' },
    ],
  },
  {
    id: 'ch6',
    num: 6,
    title: 'Participating Life Insurance Policies',
    page: 105,
    concepts: [
      { id: 'c6-01', term: 'What a participating policy is', fact: 'A \u201Cwith-profits\u201D policy that shares in the performance of the insurer\u2019s participating fund through bonuses. All par policies must be written in the par fund, and the insurer must pay guaranteed benefits regardless of fund performance, injecting its own capital if the fund falls short. Common par products: Whole Life, Endowment, Anticipated Endowment.', trap: 'Par fund assets are pooled and NOT identifiable per policy owner; contrast an ILP where each owner holds visible units.' },
      { id: 'c6-02', term: 'Guaranteed vs non-guaranteed benefits', fact: 'Guaranteed = sum assured plus guaranteed cash values. Non-guaranteed = bonuses, whose level depends on investment performance (usually the most important), expenses and claims. Once a bonus is added it generally cannot be taken away.' },
      { id: 'c6-03', term: 'Smoothing', fact: 'Insurers hold back bonuses in good years to sustain them in bad years, so declared bonuses do not track market swings. Assess a par policy\u2019s guaranteed and non-guaranteed parts in totality: a higher guaranteed proportion implies a conservative bond-heavy mandate, while a higher-bonus design leans on volatile assets like equities.' },
      { id: 'c6-04', term: 'Reversionary (annual) bonus: SRB vs CRB', fact: 'An addition to the sum assured, declared annually and vested on the policy anniversary; once declared it is guaranteed. Simple Reversionary Bonus (SRB) is calculated on the sum assured only, giving level bonuses. Compound Reversionary Bonus (CRB) is calculated on the sum assured PLUS bonuses already attached, giving increasing bonuses through compounding.', trap: 'SRB = on sum assured only (level); CRB = on sum assured + attached bonuses (compounding).' },
      { id: 'c6-05', term: 'Terminal bonus', fact: 'Added only on termination (maturity, death, TPD or surrender), usually after a minimum period in force (e.g. 25 years). It is a percentage of the RBs attached or of the basic SA. It is NOT added to the sum assured of an in-force policy and fluctuates more than the RB because it fine-tunes the fairness of smoothing.', trap: 'Terminal bonus is only credited at termination, never to a live in-force policy, and swings more than reversionary bonus.' },
      { id: 'c6-06', term: 'Interim bonus & cash dividends', fact: 'An interim bonus is paid to policies that terminate early in the year before the annual bonus declaration is finalised (declaration is typically March/April, after audited accounts). Some par policies instead pay cash dividends, which can be converted to paid-up additions or used to reduce premiums.' },
      { id: 'c6-07', term: 'How bonuses are determined', fact: 'The Appointed Actuary analyses the fund each year and recommends both the bonus to allocate and the amount to reserve for future bonuses. The Board of Directors approves it. Three guiding considerations: fairness/equity between classes and generations, solvency of the fund, and consistency with stable medium-to-long-term returns.', trap: 'Investment risk is usually the largest risk but not the only one; expense, mortality, morbidity and lapse/surrender risks also affect the fund.' },
      { id: 'c6-08', term: 'The 90/10 rule', fact: 'A regulatory safeguard in the Insurance Act stopping insurers from under-declaring bonuses to keep profit. The insurer\u2019s profit from the par fund is limited to one-ninth of the amount allocated to policy owners as bonus, i.e. 90% of distributable surplus to policy owners, 10% to the insurer. The insurer can only raise its own profit by raising policy owners\u2019 bonuses.', trap: 'The insurer\u2019s share is 1/9 of what is given to owners (10% of the split), not 10% of the whole fund computed separately.' },
      { id: 'c6-09', term: 'Reserving (RBC framework)', fact: 'Under the Risk-Based Capital framework the actuary annually values the policy liability and reserves for guaranteed benefits, future non-guaranteed bonuses, and a Provision for Adverse Deviation (PAD).' },
      { id: 'c6-10', term: 'Par disclosure', fact: 'At point of sale: a Product Summary (company-specific: how this insurer does risk-sharing, investment and smoothing) and a Policy Illustration (projected at two rates, e.g. 3.75% and 5.25%, where the higher cannot exceed LIA\u2019s maximum best-estimate long-term return; client and representative sign EVERY page). Post-sale: an Annual Bonus Update. \u201CYour Guide to Participating Policies\u201D is a generic MoneySENSE Q&A publication, provided on request and NOT compulsory.', trap: 'The Policy Illustration\u2019s higher projection rate is capped by LIA\u2019s maximum best-estimate return, and both parties sign every page.' },
      { id: 'c6-11', term: 'Participating fund governance', fact: 'Every insurer with a par fund must maintain an Internal Governance Policy, approved and reviewed annually by the board. It is not required to be disclosed to consumers, though insurers may choose to.' },
    ],
  },
  {
    id: 'ch7',
    num: 7,
    title: 'Investment-linked Policies (ILPs): Types, Features, Benefits, Risks',
    page: 133,
    concepts: [
      { id: 'c7-01', term: 'What an ILP is', fact: 'A life policy combining protection and investment: premiums buy insurance cover and units in professionally managed sub-funds. The Insurance Act defines it as a policy whose benefits are calculated by reference to units whose value relates to the market value of underlying assets. Its single most important consequence: an ILP provides NO guaranteed cash value.', trap: 'ILPs have no guaranteed cash value; the policy value rises and falls entirely with sub-fund performance and the owner bears the investment risk.' },
      { id: 'c7-02', term: 'Purpose and types of ILPs', fact: 'Three purposes: investment, savings and protection. Classified two ways: by premium frequency (single premium, savings-focused, top-ups form a \u201Crecurring single premium\u201D; vs regular premium, usually for protection with variable cover) and by product features (Investment-linked Whole Life, Endowment, and Annuity/Variable Annuity).' },
      { id: 'c7-03', term: 'Features of ILPs', fact: 'Protection (death is the minimum benefit), top-ups (anytime, usually 100% allocation), sub-fund switching (an automatic scheduled switch is an \u201Cautomatic sub-fund switch\u201D), partial/full surrender (withdrawal = partial, surrender = all units), premium holiday (stop paying while the insurer sells units to cover charges), and riders.' },
      { id: 'c7-04', term: 'Four factors before purchasing an ILP', fact: 'Insurance protection needs, risk profile, personal investment objective, and time horizon. Regular-premium ILPs carry heavy early-year charges, so a long horizon matters. For older clients the deciding issue is usually the ability to sustain premiums into retirement.', trap: 'A regular-premium ILP is unsuitable for an older client whose aim is investment and who cannot keep paying past retirement: high initial costs plus a short horizon cripple returns.' },
      { id: 'c7-05', term: 'CPF and ILPs (CPFIS)', fact: 'CPF savings can fund an ILP only under the CPF Investment Scheme (CPFIS), and only single-premium plans are allowed. Members who bought regular-premium plans before 2010 may continue paying using CPF.', trap: 'Under CPFIS only single-premium ILPs are allowed (pre-2010 regular plans are grandfathered).' },
      { id: 'c7-06', term: 'ILP vs traditional policy (4 differences)', fact: '1) Bonuses: par pays reversionary/terminal bonuses; an ILP just tracks unit values. 2) Returns: par guarantees a minimum surrender value; an ILP guarantees no minimum. 3) Premium breakdown: par is bundled; ILP charges are unbundled and transparent. 4) Mandate: par premiums go into the insurer\u2019s life fund (mostly bonds); each ILP sub-fund follows its own mandate with daily unit prices.' },
      { id: 'c7-07', term: 'Pricing of units: offer, bid, spread', fact: 'Offer price is what you pay to be allocated units. The bid-offer spread (usually ~5%) is an initial sales charge covering set-up costs: you buy at offer, sell at bid. Single pricing uses one price for buying and selling with the initial sales charge stated separately, so only the net premium buys units.', trap: 'Bid-offer (dual) pricing: buy at offer, sell at bid, spread ~5%. Single pricing: one price, sales charge disclosed separately.' },
      { id: 'c7-08', term: 'Premium allocation rate', fact: 'For single premiums and top-ups, usually 100% buys units. For regular premiums it depends on the loading structure. Front-end loading allocates less than 100% in early years, rising to 100% (sometimes above later). Back-end loading allocates 100% from the start but charges a fee on early surrender. The overall cost effect is similar either way.' },
      { id: 'c7-09', term: 'Forward pricing', fact: 'Most ILPs use forward pricing: after market close the manager recomputes the sub-fund\u2019s NAV, deducts the management charge, and divides by total units. Orders settle at the next computed price, buying at the next offer and selling at the next bid.' },
      { id: 'c7-10', term: 'ILP fees and charges', fact: 'Charges are met by premium deduction and/or selling units (converted at the BID price). Eight types: initial sales charge (bid-offer spread, 3-5%), sub-fund management fee (0.5-2% p.a.), benefit/insurance charge (rises with age), policy fees, administrative charges, surrender charges/back-end loads, premium holiday charges, and switching charges (first switch usually free).' },
      { id: 'c7-11', term: 'Level premium but rising cost of insurance', fact: 'The cost of insurance rises with age, yet the premium can stay level because units are sold each month to pay the rising charge. If the sub-fund performs poorly the units may become inadequate, forcing the owner to raise premiums or cut cover. Higher chosen protection consumes more units, leaving fewer to build cash value.', trap: 'Poor fund performance plus rising insurance charges can exhaust the units and force a top-up or reduced cover.' },
      { id: 'c7-12', term: 'Risks of investing in ILPs', fact: '1) Investment returns are not guaranteed (owner bears full risk). 2) Insurance charges are not guaranteed: for regular-premium ILPs the scale can be revised, but only across an entire class of policies and only on a sustained worsening of claims, never a single policy. 3) Units may become insufficient to pay insurance charges.' },
      { id: 'c7-13', term: 'ILP vs unit trust', fact: 'Same tax treatment and investment basis, but an ILP provides insurance cover (a death benefit) plus investment while a unit trust is investment only. ILPs need no trustee/registrar. Free-look period: 14 days for an ILP (from receiving the policy) vs 7 calendar days for a unit trust. ILPs fall under the Insurance Act and MAS Notice 307; unit trusts under the Code on Collective Investment Schemes and the SFA.', trap: 'Free-look: 14 days for an ILP, 7 days for a unit trust. ILP = MAS Notice 307.' },
    ],
  },
  {
    id: 'ch8',
    num: 8,
    title: 'Investment-linked Sub-Funds',
    page: 155,
    concepts: [
      { id: 'c8-01', term: 'Accumulation vs distribution structure', fact: 'Accumulation ploughs investment income back into the fund, enhancing unit prices. Distribution pays income out to owners (as additional units or dividends); the unit price still moves with capital gains/losses, but the owner receives regular income.', trap: 'Accumulation reinvests income (no payout); distribution pays it out.' },
      { id: 'c8-02', term: 'Fund relationship definitions', fact: 'Mother fund: an earlier existing fund that later funds tap into. Feeder fund: feeds directly into the mother fund, so it experiences the same unit-price fluctuations. Mirror fund: designed to closely duplicate the composition of an existing fund. Portfolio: a preset mix of funds matched to a risk profile.', trap: 'A feeder fund shares the mother fund\u2019s price movements; a mirror fund merely copies its composition.' },
      { id: 'c8-03', term: 'Types of sub-funds and horizons', fact: 'Equity (stocks, medium-high risk, ~10yr). Bond/fixed income (income; interest-rate, credit and reinvestment risk; medium, ~4yr). Cash/money-market (low risk, up to 3yr, capital unlikely to fall). Managed/balanced (~4yr). Geographically specialised (high risk, ~10yr). Sector/specialised. Property. Capital-guaranteed.' },
      { id: 'c8-04', term: 'Property funds: redemption deferral', fact: 'Because property is illiquid, property funds normally allow the manager to defer unit redemptions for up to 12 months, except on death.', trap: 'Property fund redemptions can be deferred up to 12 months, but never on a death claim.' },
      { id: 'c8-05', term: 'Capital-guaranteed funds', fact: 'Promise a minimum return by putting most money in bonds to preserve capital and the balance in derivatives (usually options) for growth. Commonly closed-end (limited subscription period, fixed maturity), tenure around 4-7 years.', trap: 'Capital-guaranteed = mostly bonds for safety plus derivatives for upside, usually closed-end.' },
      { id: 'c8-06', term: 'Managed fund vs managed portfolio', fact: 'A managed (balanced) fund is one fund with one manager choosing which assets to buy. A managed portfolio (risk-rated/lifestyle fund) is multiple funds with one manager choosing which funds to invest in.', trap: 'Managed fund picks assets; managed portfolio picks funds.' },
      { id: 'c8-07', term: 'Switching facility', fact: 'Lets the owner move part or all of their money between funds, usually with a limited number of free switches per year. Useful in retirement and education planning: as the target date nears, switch from volatile equity funds into more stable cash or fixed-income funds.' },
      { id: 'c8-08', term: 'Fund switching vs product switching (churning)', fact: 'Legitimate fund switching moves money between sub-funds. Improper product switching is when an errant adviser gets a client to surrender one product and buy another with no real benefit, purely to churn commissions. This is prohibited misconduct.', trap: 'Product switching (churning) for commissions is misconduct; fund switching within an ILP is legitimate.' },
    ],
  },
  {
    id: 'ch9',
    num: 9,
    title: 'ILPs: Computational Aspects',
    page: 163,
    concepts: [
      { id: 'c9-01', term: 'Time value of money & compounding', fact: 'A dollar today is worth more than a dollar later because it can earn a return. M9 uses compound interest throughout: interest is earned on principal plus accumulated interest, unlike simple interest which applies the rate to the original principal only.', trap: 'Every M9 computation uses compound, not simple, interest.' },
      { id: 'c9-02', term: 'FV and PV formulas', fact: 'FV = PV x (1 + i)^n (compounding forward). PV = FV / (1 + i)^n (discounting back). In compounding, FV rises with i and n. In discounting, PV falls as i or n rises: a higher rate or longer time means you need less money today.' },
      { id: 'c9-03', term: 'Nominal vs effective rate', fact: 'A quoted rate ignoring compounding frequency is nominal; the rate including compounding is effective, and the effective rate is always higher. 10% nominal compounded semi-annually = 10.25% effective. More frequent compounding gives a higher FV and lower PV.', trap: 'The effective rate is always higher than the nominal rate; they are equal only with annual compounding.' },
      { id: 'c9-04', term: 'Future offer price & units bought', fact: 'Grow today\u2019s offer price by the growth rate: Offer Price = current OP x (1 + i)^n, then Units = Premium / Offer Price. Count periods carefully: \u201Cbeginning of Year 4\u201D means end of Year 3 = 3 compoundings, not 4.', trap: '\u201CBeginning of Year 4\u201D = 3 compounding periods, not 4. Miscounting periods is the classic error.' },
      { id: 'c9-05', term: 'Death benefit: the four methods', fact: 'Let u = value of units (at bid price) and v = sum assured. DB1 = u (units only). DB2 = v (sum assured only). DB3 = u + v (units PLUS sum assured). DB4 = higher of u or v. DB3 and DB4 are the heavily tested pair.', trap: 'DB3 = units + sum assured; DB4 = the HIGHER of units or sum assured. Do not swap these.' },
      { id: 'c9-06', term: 'DB3 gives higher benefit and higher charges', fact: 'For the same sum assured, DB3 (u + v) always pays a higher death benefit than DB4 (higher of u or v). A higher death benefit means a higher mortality charge.', trap: 'DB3 always costs more in mortality charges than DB4 because it pays more.' },
      { id: 'c9-07', term: 'Mortality charge under DB3 vs DB4', fact: 'Monthly charge = (q/12) x (the part of the death benefit not covered by units), where q is the annual cost per $1,000 of cover. DB3: units offset nothing, so charge = (q/12) x v. DB4: units offset the sum assured, so charge = (q/12) x (v \u2212 u), or zero if u \u2265 v.', trap: 'DB3 is charged on the full sum assured; DB4 only on the excess of v over u (zero once units exceed the sum assured).' },
      { id: 'c9-08', term: 'Allocation rates', fact: 'The percentage of premium used to buy units. Single premiums and top-ups usually allocate 100%. Regular premiums under front-end loading start low and rise (e.g. Y1 15%, Y2 30%, Y3 50%, Y4-9 100%, then 102% bonus units to reward persistency).' },
      { id: 'c9-09', term: 'Computing units allocated (after-allocation)', fact: 'Deducting charges after allocation converts them to units at the BID price, so the spread bites. Steps: units purchased = (allocation% x premium) / offer price; bid = (1 \u2212 spread) x offer price; total charges = policy fee + admin + mortality; units cancelled = charges / bid; units remaining = purchased \u2212 cancelled + any prior balance.', trap: 'Charges are always converted to units at the BID price, not the offer price.' },
      { id: 'c9-10', term: 'Withdrawal vs surrender', fact: 'Withdrawal (partial): units cancelled = withdrawal amount / bid price, subject to a minimum balance. Surrender (full): surrender value = units x current bid price, less any surrender charges. You always cash out, whether withdrawing or surrendering, at the BID price.', trap: 'Both withdrawal and surrender are valued at the bid price.' },
      { id: 'c9-11', term: 'Return on gross premium', fact: 'The compound rate turning your single premium into the eventual surrender value. Set Premium x (1 + i)^n = cash value, solve for the factor, then find the closest FVIF table match. E.g. 10,000 x (1+i)^10 = 17,947 gives a factor ~1.7947, closest to ~6% p.a.' },
    ],
  },
  {
    id: 'ch10',
    num: 10,
    title: 'Annuities',
    page: 187,
    concepts: [
      { id: 'c10-01', term: 'What an annuity is', fact: 'A contract providing a guaranteed income to the annuitant for life (or a shorter set period). It is the opposite of life insurance: life insurance protects against dying too soon, an annuity protects against living too long (longevity risk). Bought with cash or CPF savings.', trap: 'Annuity = protection against living too long; life insurance = protection against dying too soon.' },
      { id: 'c10-02', term: 'CPF LIFE', fact: 'The national longevity annuity scheme: a monthly payout from the payout eligibility age for as long as the member lives. Three plans: Standard (default, higher payouts), Basic (opt-in, lower payouts), Escalating (opt-in, starts lower and rises 2% yearly). Choice of payout age 65 or 70; each year deferred raises payouts by about 7%.' },
      { id: 'c10-03', term: 'Accumulation vs payout period', fact: 'The owner (usually also the annuitant) pays a single premium (the purchase price/consideration) or a series of premiums, which the insurer invests. The accumulation period runs from first premium until payouts begin; the payout period is while income is paid.' },
      { id: 'c10-04', term: 'Immediate annuity', fact: 'Payout starts one payment period after purchase and MUST be bought with a single lump-sum premium. Before payouts begin, death or cancellation usually refunds the purchase price. After payouts begin, death ends the policy unless a survivor/refund benefit or minimum guarantee period applies.', trap: 'An immediate annuity can only be bought with a single premium.' },
      { id: 'c10-05', term: 'Deferred annuity', fact: 'Payments begin on a future date, bought by single OR regular premiums (single most common). The CPF Minimum Sum can only buy a DEFERRED annuity, not an immediate one. CPF LIFE auto-includes members with over $40,000 in the Retirement Account at 55, or over $60,000 at 65.', trap: 'CPF Minimum Sum monies can only fund a deferred annuity.' },
      { id: 'c10-06', term: 'Payout options: life annuities', fact: 'Pure Life Annuity (straight life) pays until death and nothing after, so dying early means receiving far less than paid. Guaranteed Minimum Payout annuities give lower income but add protection: Life Annuity with Period Certain (pays the beneficiary until the period ends if the annuitant dies early) and Life Income with Refund (refunds any shortfall below the purchase price).', trap: 'A pure life annuity stops at death with nothing left; guaranteed-minimum versions pay less but protect the estate.' },
      { id: 'c10-07', term: 'Temporary (non-lifetime) annuities', fact: 'Fixed Period: pays until the specified period ends OR death, whichever is first. Fixed Amount: pays until the total reaches a specified maximum OR death, whichever is first.' },
      { id: 'c10-08', term: 'Bonus entitlement & lives covered', fact: 'Participating annuities share profits via bonuses (payouts fluctuate but never fall below the guaranteed minimum); non-participating (most common) stay fixed. Lives: single life (most common), joint life (ends when one dies), joint & survivor (pays until all die, benefit may drop to e.g. 50% after the first death).' },
      { id: 'c10-09', term: 'Benefits & limitations of annuities', fact: 'Benefits: annuity payouts are free from income tax (except those from a partnership, the SRS, or an employer-bought annuity replacing a pension), plus guaranteed income and tax-free accumulation returns. Limitations: no death protection (buy only after death cover is in place), no major-illness cover, and most do not counter inflation.', trap: 'Annuity payouts are tax-free except from a partnership, SRS, or an employer annuity replacing a pension/employment benefit.' },
    ],
  },
  {
    id: 'ch11',
    num: 11,
    title: 'Application And Underwriting',
    page: 201,
    concepts: [
      { id: 'c11-01', term: 'Proposal form as basis of the contract', fact: 'The application form is the primary source of risk information. It is incorporated into the policy and forms the basis of the contract and any claim, so it must be completed truthfully under utmost good faith.' },
      { id: 'c11-02', term: 'Warning statement & never signing for the client', fact: 'The warning statement highlights the duty to disclose all facts known or ought to be known; non-disclosure lets the insurer void the policy from inception with nothing payable. The adviser must NEVER sign the proposal form on behalf of the proposer, and the client must countersign any change.', trap: 'Non-disclosure voids the policy from inception (nothing paid). Never sign the form for the client.' },
      { id: 'c11-03', term: 'Backdating', fact: 'Backdating to just before the last birthday secures a lower premium (charged on a next-birthday basis). Maximum backdating is 6 months, and it is not available for some policies such as ILPs.', trap: 'Backdating is capped at 6 months and lowers the premium; not allowed on ILPs.' },
      { id: 'c11-04', term: 'Third-party particulars & replacement disclosure', fact: 'Particulars of the proposer are completed only for third-party policies, where the relationship confirms insurable interest. On replacement of existing policies the insurer must state the disadvantages and offer to return premiums if the owner decides not to replace, guarding against improper switching.' },
      { id: 'c11-05', term: 'Free-look & bankrupt restriction', fact: 'The declaration states the 14-day free-look period (refund of premium less risk-assessment cost, or a full refund if the insurer rejects the proposal) and notes that undischarged bankrupts cannot buy new policies without the Official Assignee\u2019s consent.' },
      { id: 'c11-06', term: 'Factors affecting the risk', fact: 'Age is the \u201Cpoint of departure\u201D (from the mortality table). Occupation, physical condition and medical history follow. Financial condition is a key indicator of MORAL hazard, preventing over-insurance: the sum assured should bear a reasonable relationship to income.', trap: 'Financial condition is the main moral-hazard check; the sum assured must be justified by income.' },
      { id: 'c11-07', term: 'Medical vs non-medical & HIV testing', fact: 'Most proposals are underwritten non-medically; whether an exam is required depends on age, sum assured, and medical history. The HIV antibody test is compulsory for certain occupations and at a sum assured above $1m (all ages). The Lifestyle questionnaire is used solely to assess AIDS risk (over $1m or certain occupations).', trap: 'HIV test and Lifestyle questionnaire kick in above a $1m sum assured or for certain occupations.' },
      { id: 'c11-08', term: 'Underwriting decision & accepting higher risk', fact: 'Standard risk pays the ordinary rate. Four ways to accept a higher risk: ordinary rate with a lien, with a change in plan, with an exclusion, or with extra premiums. A lien pays SA less a % if death is within the lien period (common for young children). Substandard means extra terms; uninsurable means postpone or decline.', trap: 'The four higher-risk options: lien, change of plan, exclusion, or extra premium.' },
      { id: 'c11-09', term: 'Commencement of risk', fact: 'Standard terms: the insurer sends a letter of acceptance and cover starts on receipt of the first premium within a set window (e.g. 30 days); if premium accompanied the application, cover starts immediately on acceptance. Sub-standard: a conditional acceptance letter requiring signature, return and the extra premium.' },
      { id: 'c11-10', term: 'Group life underwriting factors', fact: 'The group must exist for a purpose other than obtaining insurance (reduces anti-selection). Consider stability, size (minimum usually 3 or 5), nature of business and employee classes. For contributory plans, minimum participation of about 70-90% guards against anti-selection. Previous claims experience usually covers the past 3 years.', trap: 'Contributory group plans need ~70-90% participation to control anti-selection.' },
    ],
  },
  {
    id: 'ch12',
    num: 12,
    title: 'Policy Services',
    page: 221,
    concepts: [
      { id: 'c12-01', term: 'Premium payment methods & CPF/SRS', fact: 'Payment can be by cash, cheque, NETS, GIRO, Banker\u2019s Order, credit card, and more. CPF Ordinary & Special Accounts (CPFIS) can fund Endowment, Annuity and ILP, but only by single or recurrent single premium. SRS is likewise single/recurrent single only.', trap: 'CPFIS and SRS can only pay single or recurrent single premiums, not regular premiums.' },
      { id: 'c12-02', term: 'Conditional Premium Deposit Receipt', fact: 'Also called an interim/temporary cash receipt, issued by the adviser at the close of sale. It binds the insurer to conditional cover for ACCIDENTAL DEATH only before official acceptance, typically for death within about 90 days, capped at a sum often under $500,000 or the sum applied for, whichever is lower.', trap: 'The conditional receipt covers accidental death ONLY, capped (often under $500k), pending acceptance.' },
      { id: 'c12-03', term: 'Policy alterations & sum assured changes', fact: 'Insurers generally refuse alterations that increase their liability. Increasing the sum assured is generally NOT allowed except for ILPs (non-ILPs usually only in the first year, with a health declaration). Reducing the SA: if the policy has no cash value the reduced portion lapses; if it has cash value, that portion is \u201Csurrendered\u201D.', trap: 'Increasing the sum assured is generally allowed only on ILPs.' },
      { id: 'c12-04', term: 'Duplicate policy: contract vs evidence', fact: 'The policy document is only EVIDENCE of the contract; the contract still exists even if the document is lost, so insurers will usually still pay a claim (with a letter of indemnity). A duplicate needs a written request, a statutory declaration, an indemnity, and payment of the duplication cost.', trap: 'Losing the policy document does not void cover; the contract exists independently of the paper.' },
      { id: 'c12-05', term: 'Assignment of policy', fact: 'Assignment transfers rights and ownership: absolute (all rights transferred) or conditional/collateral (rights revert on a condition, e.g. a loan repaid). Under the Civil Law Act s4(8) an absolute assignment must be absolute, in writing, and with written notice served on the insurer. A person over 10 can hold a policy but cannot surrender or assign it.', trap: 'Absolute assignment needs all three: absolute, in writing, and written notice to the insurer.' },
      { id: 'c12-06', term: 'Policy loans', fact: 'A cash-value policy can be collateral. Interest is typically 5-8%, accrues daily and compounds on each policy anniversary; unpaid interest is added to the principal. If loan plus accrued interest exceeds the cash value, the insurer terminates the policy with no premium refund. A loan reduces the claim or surrender amount.', trap: 'When loan + interest exceeds the cash value, the policy is terminated.' },
      { id: 'c12-07', term: 'Lapsing', fact: 'A policy lapses when premiums are unpaid within the grace period BEFORE any cash value is acquired, or when it is on Automatic Premium Loan and the cash value is exhausted. Causes include financial difficulty, mis-selling, churning (errant own adviser) and twisting (competing adviser).', trap: 'Twisting is by a competing adviser; churning is by the client\u2019s own errant adviser.' },
      { id: 'c12-08', term: 'Reinstatement', fact: 'Usually allowed within 2-3 years of lapse. The owner pays all arrears plus interest. Evidence of continued insurability is the MOST important condition, because it prevents anti-selection. On reinstatement the incontestability and suicide clauses restart.', trap: 'Evidence of insurability is the key reinstatement condition; incontestability and suicide clauses reset.' },
      { id: 'c12-09', term: 'Surrender & its alternatives', fact: 'Insurers must pay a surrender value for policies with cash value that have been in force at least 3 years. Always discourage surrender (lost cover, possible uninsurability). Alternatives: policy loan, more frequent premium mode, surrender only bonuses, paid-up, ETI, reduce the sum assured, or a premium holiday (selected ILPs). A bankrupt cannot surrender; the interest vests in the Official Assignee.', trap: 'Surrender value is payable once the policy has cash value and has run at least 3 years; a bankrupt cannot surrender.' },
    ],
  },
  {
    id: 'ch13',
    num: 13,
    title: 'Life Insurance Claims',
    page: 241,
    concepts: [
      { id: 'c13-01', term: 'Core idea of claims', fact: 'The insurer must pay the right person the right amount, promptly. Every claims rule is machinery for establishing entitlement.' },
      { id: 'c13-02', term: 'Proper claimants', fact: 'The deceased\u2019s executors, or the deceased\u2019s spouse, child, parent, sibling or relatives. An illegitimate child is treated as legitimate. The insurer may require a statutory declaration to confirm the claimant qualifies.' },
      { id: 'c13-03', term: 'Payment without probate', fact: 'Under s61(2) the insurer may make an advance payment up to a prescribed amount without a Grant of Probate or Letter of Administration. The prescribed limit is $150,000.', trap: 'The no-probate advance limit is $150,000.' },
      { id: 'c13-04', term: 'Joint tenancy vs tenancy in common', fact: 'Joint tenancy: on one owner\u2019s death the share passes to the surviving tenant(s), so joint-life policies are usually written this way. Tenancy in common: the deceased\u2019s share passes to their own estate and then their beneficiaries.', trap: 'Joint tenancy passes to the survivor; tenancy in common passes to the deceased\u2019s estate.' },
      { id: 'c13-05', term: 'The three proofs', fact: 'Proof of death (the death certificate, issued in Singapore by ICA). Proof of age (NRIC or birth certificate, needed only if age was not admitted at inception). Proof of title (who is entitled to the proceeds).', trap: 'Proof of age is only required if age was NOT admitted when the policy was issued.' },
      { id: 'c13-06', term: 'Proof of title: six routes', fact: 'Policy owner (third-party policy), assignee (assigned policy), trustee, executor with Grant of Probate (there is a Will), or administrator with Letter of Administration (no Will). Memory: Will \u2192 Probate \u2192 Executor; No Will \u2192 LOA \u2192 Administrator.', trap: 'Will means Probate and an Executor; no Will means a Letter of Administration and an Administrator.' },
      { id: 'c13-07', term: 'Statutory presumption of death', fact: 'Apply to court after a disappearance without trace for 7 or more years. The court presumption is NOT binding on the insurer, which can make its own enquiries.', trap: 'Presumption of death needs 7 years missing and does not bind the insurer.' },
      { id: 'c13-08', term: 'Maturity & annuity claim specifics', fact: 'For a maturity claim the insurer writes ~1-2 months before maturity for a discharge voucher; proof of survival is needed for a Pure Endowment. For annuities, proof the annuitant is alive is given via an \u201CAffirmation Form\u201D witnessed by someone over 21 who is not immediate family and not a joint account holder.', trap: 'A Pure Endowment maturity claim requires proof the insured survived.' },
      { id: 'c13-09', term: 'LIA Register of Unclaimed Proceeds', fact: 'Launched 4 Jan 2016; lets the public search for death/maturity proceeds unclaimed for more than 12 months. Updated every 6 months, showing policyholder name, masked ID and insurer name.' },
    ],
  },
  {
    id: 'ch14',
    num: 14,
    title: 'The Insurance Contract',
    page: 253,
    concepts: [
      { id: 'c14-01', term: 'Void, voidable, valid', fact: 'Valid = enforceable. Void = never had legal existence. Voidable = one party may choose to avoid it.', trap: 'Void means it never existed; voidable means it stands until the innocent party chooses to avoid it.' },
      { id: 'c14-02', term: 'Offer and acceptance in life insurance', fact: 'The proposal form plus first premium is THE OFFER; the insurer issuing the policy is ACCEPTANCE. An advertisement or brochure is only an invitation to treat, and a conditional acceptance is a counter-offer.', trap: 'The client makes the offer (form + premium); the insurer accepts by issuing. An ad is just an invitation to treat.' },
      { id: 'c14-03', term: 'Capacity to contract (minors)', fact: 'Capacity is limited for minors, the mentally disordered, drunken persons, and undischarged bankrupts. A person over 10 can enter an insurance contract; under 16 needs written parental consent. A minor cannot assign, mortgage, surrender or give valid discharge until 18.', trap: 'Over 10 can hold a policy, but cannot assign or surrender it until 18.' },
      { id: 'c14-04', term: 'Consensus ad idem & utmost good faith', fact: 'A genuine meeting of minds is required. Ordinary sales use caveat emptor (buyer beware); insurance uses uberrima fides (utmost good faith) because only the proposer knows their own risks. The duty binds both parties.' },
      { id: 'c14-05', term: 'Material fact & prudent insurer test', fact: 'A material fact is a circumstance that would influence the judgement of a prudent insurer in fixing the premium or deciding to take the risk. The prudent-insurer test is OBJECTIVE: the insured\u2019s honest belief that a fact was immaterial does not excuse non-disclosure. The misrepresentation must also have induced the insurer to contract.', trap: 'Materiality is judged objectively by a prudent insurer, not by the applicant\u2019s honest opinion.' },
      { id: 'c14-06', term: 'Warranties vs representations & basis clause', fact: 'A warranty is guaranteed true in every respect; if false in any respect (even immaterial) the insurer can avoid ab initio. A basis clause turns proposal answers into warranties. A representation need only be true as to material facts. In Singapore, absent fraud, all statements are deemed representations, not warranties.', trap: 'The LIA no longer allows a basis clause on the owner\u2019s OWN life, though it remains valid for \u201Clife of another\u201D policies.' },
      { id: 'c14-07', term: 'Section 25(5) warning', fact: 'Proposal forms must prominently display a warning that non-disclosure of facts known or ought to be known may mean nothing is payable, letting the insurer declare the contract void from inception.' },
      { id: 'c14-08', term: 'Contra proferentem & waived answers', fact: 'An ambiguous question is construed against the drafter (the insurer), so doubt favours the insured. Where the proposal form and policy conflict, the policy prevails as the later document. If the insurer issues despite an unanswered question, it is deemed to have waived the answer.', trap: 'Ambiguity is read against the insurer who drafted it (contra proferentem).' },
      { id: 'c14-09', term: 'Breach of good faith: fraud vs innocence', fact: 'Fraud lets the insurer keep the premium; innocence does not. Innocent non-disclosure: avoid ab initio (if material) but return the premium. Fraudulent non-disclosure: avoid and keep the premiums. Fraudulent misrepresentation: avoid, claim damages, and retain premiums.', trap: 'The insurer keeps premiums only where there was fraud; innocent breaches require a refund.' },
      { id: 'c14-10', term: 'Six vitiating factors', fact: 'Misrepresentation, duress and undue influence make a contract VOIDABLE (the innocent party chooses). Illegality and mistake make it VOID. Non est factum (\u201Cthis is not my deed\u201D) lets someone who signed a fundamentally different document, without carelessness, avoid it. A policy without insurable interest is an illegal wagering contract, hence void.', trap: 'Misrep/duress/undue influence = voidable; illegality/mistake = void. No insurable interest = void wager.' },
      { id: 'c14-11', term: 'Waiver and estoppel', fact: 'Waiver is the intentional, voluntary relinquishment of a known right (express or by conduct). Estoppel arises when a party creates the impression a fact exists, an innocent party relies and suffers, and so the insurer is barred from denying it.' },
      { id: 'c14-12', term: 'Grace period & age misstatement', fact: 'Grace period is usually 30/31 days to pay an overdue premium with cover continuing; death in the grace period has the outstanding premium deducted. Age misstatement: understated age reduces the sum assured to what the premium would have bought at true age; overstated age refunds the excess premium WITHOUT interest.', trap: 'Understated age cuts the sum assured; overstated age refunds excess premium without interest.' },
      { id: 'c14-13', term: 'Suicide & incontestability clauses', fact: 'Suicide within the specified period (usually 1 year from issue/reinstatement) voids the policy and refunds premiums without interest; after the period, the claim is paid even for suicide, sane or insane. Incontestability: after the policy runs 1-2 years, the insurer cannot dispute validity except for fraud (and non-payment).', trap: 'Suicide after the 1-year period is PAID; incontestability blocks disputes after 1-2 years except for fraud.' },
      { id: 'c14-14', term: 'Free-look & non-forfeiture (traditional only)', fact: 'Free-look is 14 days after delivery with a full refund less medical fees (ILPs also adjust for unit-price change). Non-forfeiture options apply to cash-value TRADITIONAL policies only, NOT ILPs: a policy in force over 3 years will not lapse for non-payment. If no option is elected, APL advances cash value until exhausted, then the policy lapses.', trap: 'Non-forfeiture options are for traditional cash-value policies, never ILPs.' },
    ],
  },
  {
    id: 'ch15',
    num: 15,
    title: 'Law Of Agency',
    page: 277,
    concepts: [
      { id: 'c15-01', term: 'Agent as fiduciary', fact: 'An adviser is an agent, legally authorised to bring the principal (insurer) into a contract with a third party (client). An agent is a fiduciary who must act in the principal\u2019s best interest. Life agents are legally \u201Crepresentatives\u201D under the FAA.' },
      { id: 'c15-02', term: 'Creation of an agency', fact: 'Express (by deed, written contract or orally; the Insurance Act requires a WRITTEN agreement between insurer and agent), implied (from conduct), by situation (e.g. every partner is an agent of the firm), or by operation of law (agency by necessity).', trap: 'The Insurance Act requires the insurer-agent agreement to be in writing.' },
      { id: 'c15-03', term: 'Duties of an agent', fact: 'Common law: carry out the mandate within authority, exercise due care and skill, account for and separate money, act honestly, inform the principal of material facts. Fiduciary: do not delegate authority, avoid conflicts of interest, take no bribes or secret commissions, and do not exploit the position for personal gain.' },
      { id: 'c15-04', term: 'Dual-agency rule', fact: 'An intermediary may act for BOTH sides depending on the task. Agent of the INSURER when explaining policy terms, collecting premiums, issuing a cover note, or acting under delegated authority. Agent of the INSURED when advising on cover required, advising how to make a claim, or completing (but NOT signing) the proposal form.', trap: 'Completing the proposal form makes you the insured\u2019s agent; collecting premiums makes you the insurer\u2019s agent. Never sign the form.' },
      { id: 'c15-05', term: 'Four types of authority', fact: 'Actual/express (set out in the agency contract), implied (whatever is necessary to carry out the express authority), usual (may explain proposal questions and policy terms), and apparent/ostensible (the agent lacks actual authority but a third party reasonably believes it exists based on the PRINCIPAL\u2019S conduct).', trap: 'Apparent authority rests on the principal\u2019s conduct, not the agent\u2019s; insurers are bound by transactions under it.' },
      { id: 'c15-06', term: 'Limits of usual authority', fact: 'Under usual authority an agent may explain proposal questions and policy terms, but CANNOT enter, renew or revive a contract, vary terms, or waive conditions.', trap: 'Usual authority explains but cannot bind: no entering, renewing, varying or waiving.' },
      { id: 'c15-07', term: 'Acting outside authority & agent\u2019s rights', fact: 'If an agent acts outside authority the principal is not bound, but the agent can incur personal liability. An agent\u2019s rights are remuneration (usually commission) and indemnity for liabilities properly incurred, though indemnity is lost if the act was unauthorised, in breach of duty, the agent\u2019s own fault, or illegal.' },
      { id: 'c15-08', term: 'Ratification', fact: 'A principal can validate an unauthorised act if it was done for a named, ascertainable principal (an undisclosed principal cannot ratify), the principal existed and was capable at the time, the whole deal is ratified (no partial ratification), and within a reasonable time. It takes effect from the DATE OF THE AGENT\u2019S ACT, not the date of ratification.', trap: 'Ratification backdates to the agent\u2019s act and must cover the entire deal; an undisclosed principal cannot ratify.' },
      { id: 'c15-09', term: 'Termination of agency', fact: 'By the parties (revocation by the principal, renunciation by the agent) or by operation of law (expiry of agreed time, complete performance, frustration/illegality, or death, bankruptcy, disability or unsoundness of mind of either party).' },
    ],
  },
  {
    id: 'ch16',
    num: 16,
    title: 'Income Tax And Life Insurance',
    page: 285,
    concepts: [
      { id: 'c16-01', term: 'Taxable income & the capital gains rule', fact: 'Income is taxed under the Income Tax Act if it accrues in, is derived from, or is received in Singapore. Capital gains are NOT taxable, and gifts, legacies and lottery wins are not income. Exempt income includes CPF withdrawals, one-tier exempt dividends and bank deposit interest.', trap: 'Singapore has no capital gains tax; gifts, legacies and lottery winnings are not income.' },
      { id: 'c16-02', term: 'The income funnel', fact: 'Statutory Income is the full income from each source. Assessable Income = statutory income less allowable (income-producing) expenses and approved donations (deductible at 2.5x, carried forward up to 5 years). Chargeable Income = assessable income less personal reliefs, and is what is taxed. A company has no personal reliefs, so its assessable income equals its chargeable income.', trap: 'Approved donations are deducted at 2.5x their value; a company has no personal reliefs.' },
      { id: 'c16-03', term: 'Tax rates', fact: 'Applied per the Second Schedule: progressive 2%-22% for residents, with no tax if chargeable income is $20,000 or below. Non-residents are generally taxed at a flat 15%.' },
      { id: 'c16-04', term: 'Personal reliefs (residents only)', fact: 'Include earned income, NSman, spouse, qualifying/handicapped child, working mother\u2019s child, parent, grandparent caregiver, life insurance, CPF, CPF cash top-up, course fees, foreign maid levy, and SRS. Qualifying Child Relief needs the child unmarried, under 16 (or studying full-time), earning under $4,000. Foreign Maid Levy Relief is twice the levy paid.' },
      { id: 'c16-05', term: 'Life insurance relief conditions', fact: 'Premiums on the taxpayer\u2019s or wife\u2019s life (a female taxpayer: her own life only), with the insurer having a Singapore office. The deduction cannot exceed 7% of the capital sum assured (excluding bonuses). NOT eligible if total CPF contributions are $5,000 or more; if CPF is less, claim the lowest of ($5,000 \u2212 CPF), 7% of insured value, or premiums paid.', trap: 'Life insurance relief shares a combined $5,000 cap with CPF relief and is capped at 7% of the sum assured.' },
      { id: 'c16-06', term: 'Who benefits most from life insurance relief', fact: 'The self-employed with no voluntary CPF (businessmen, doctors, lawyers, accountants) and foreigners exempt from CPF, because their CPF is not already using up the $5,000 cap. Even then the benefit is small.', trap: 'Employees whose CPF already hits $5,000 get no life insurance relief; the self-employed and foreigners gain most.' },
      { id: 'c16-07', term: 'SRS contribution relief', fact: 'Voluntary top-ups reduce chargeable income, based on the Absolute Income Base (17 months of the CPF salary ceiling), capped at 15% of AIB for a citizen/PR or 35% for a foreigner.' },
      { id: 'c16-08', term: 'Relief vs rebate & Parenthood Tax Rebate', fact: 'A relief reduces chargeable income; a rebate reduces the tax payable. The Parenthood Tax Rebate is $5,000 for the 1st child, $10,000 for the 2nd, and $20,000 for the 3rd and each subsequent child (married SG residents, child a Singapore Citizen). Unused rebate is carried forward.', trap: 'Relief cuts chargeable income; a rebate cuts tax. PTR = $5k / $10k / $20k for 1st / 2nd / 3rd+.' },
      { id: 'c16-09', term: 'SRS tax benefits on withdrawal', fact: 'Only 50% is taxed if withdrawn on or after the statutory retirement age, on death, on medical grounds, or by a foreigner who held the account 10+ years; withdrawals can spread over up to 10 years. Premature withdrawal is 100% taxed plus a 5% penalty. An annuity bought via SRS has 50% of each payout taxable.', trap: 'SRS: 50% taxed at retirement, but premature withdrawal is 100% taxed plus a 5% penalty.' },
    ],
  },
  {
    id: 'ch17',
    num: 17,
    title: 'Insurance Nomination, Wills And Trusts',
    page: 297,
    concepts: [
      { id: 'c17-01', term: 'Nomination framework', fact: 'After the Insurance Amendment Act, the framework offers two deliberate choices: revocable and trust (irrevocable). It is not compulsory; with no nomination, proceeds pass by Will, or failing that under the Intestate Succession Act.' },
      { id: 'c17-02', term: 'Scope & who can nominate', fact: 'Applies only to non-indemnity policies (life and personal accident with death benefits); indemnity policies (hospital & surgical) are excluded because they reimburse the owner\u2019s own losses. The nominator must be BOTH the policy owner and the life insured, and at least 18.', trap: 'Only non-indemnity policies qualify, and you must be both owner and life insured to nominate.' },
      { id: 'c17-03', term: 'Trust (irrevocable) nomination', fact: 'The owner loses all rights; both living AND death benefits belong to the nominees (though the owner still pays premiums). Only spouse and/or children can be nominated. The owner needs the written consent of all nominees to change, revoke, take a loan or surrender. Proceeds are protected from creditors in bankruptcy.', trap: 'Trust nomination: spouse and/or children only, both living and death benefits pass, and changes need all nominees\u2019 consent.' },
      { id: 'c17-04', term: 'Trust nomination: witnesses & nominee death', fact: 'Made on a Trust Nomination Form signed before two adult witnesses (over 21) who are not nominees or their spouses; shares must total 100%. A nominee who is not the owner may be trustee. If a nominee dies before the owner, that share goes to the NOMINEE\u2019S ESTATE. Trust nomination cannot be made on DPS, CPF-funded, ElderShield Supplement, integrated medical or SRS policies.', trap: 'Under a TRUST nomination a deceased nominee\u2019s share goes to their estate (contrast revocable, where it goes to surviving nominees).' },
      { id: 'c17-05', term: 'Revocable nomination', fact: 'The owner retains full rights and can change or revoke anytime WITHOUT the nominee\u2019s consent. Only DEATH benefits go to nominees; living benefits stay with the owner. Any legal entity (including a corporation) can be nominated, but not an animal. It cannot be made if a trust nomination already exists.', trap: 'Revocable: death benefits only, owner keeps living benefits and full control, any legal entity except an animal.' },
      { id: 'c17-06', term: 'Revocable: nominee predeceases owner', fact: 'A sole nominee\u2019s death auto-revokes the nomination. With multiple nominees it is revoked only when ALL die; otherwise a deceased nominee\u2019s share is redistributed proportionally to the survivors.', trap: 'Revocable + multiple nominees: a dead nominee\u2019s share goes to the surviving nominees, not their estate.' },
      { id: 'c17-07', term: 'Policy-type restrictions', fact: 'CPFIS, CPF LIFE, DPS and SRS policies allow REVOCABLE nomination only (no trust, as the money is for the member\u2019s own retirement). A Muslim policy owner may use both types. Group insurance allows NO nomination, since the organisation owns the policy and is not the life insured.', trap: 'CPF/SRS/DPS = revocable only; group insurance = no nomination at all.' },
      { id: 'c17-08', term: 'Priority of nominations vs a Will', fact: 'A revocable nomination is a testamentary instrument with the same legal standing as a Will; where instruments conflict, the latest validly executed one prevails. A Will overrides a nomination only if it contains explicit policy details (insurer, policy number, proceeds); a Will covering \u201Call property\u201D is not enough. Trust nomination proceeds sit outside the estate entirely.', trap: 'A general Will does NOT override a nomination; it must name the specific policy. Trust proceeds never enter the estate.' },
      { id: 'c17-09', term: 'Wills', fact: 'Made by the testator, effective only on death and changeable until then; no valid Will means the Intestate Succession Act applies (or the Administration of Muslim Law Act for Muslims). The testator must be 21+ and of sound mind (exception: soldiers on active service or mariners at sea) and it must be witnessed by two persons present together. An executor needs a Grant of Probate.', trap: 'A valid Will needs a testator 21+ of sound mind and two witnesses present together.' },
      { id: 'c17-10', term: 'Intestate Succession Act shares', fact: 'Spouse only: all to spouse. Spouse + children: half to spouse, half to children. Children only: all to children. Spouse + parents: half to spouse, half to parents. Parents only: all to parents. Then siblings, then grandparents, then uncles/aunts. If none, all to the Government. A fiance(e) receives nothing.', trap: 'Spouse + children = half/half; spouse + parents (no children) = half/half; a fiance(e) gets nothing.' },
      { id: 'c17-11', term: 'Trusts', fact: 'A settlor transfers property to a trustee (legal owner) to hold in trust for the beneficiaries (beneficial owners), a duality of ownership. Express trusts need the three certainties (words, subject matter, objects). Benefits include controlled distribution, avoiding probate, confidentiality and asset protection. Estate duty was abolished in Singapore on 15 Feb 2008.', trap: 'Only a trust avoids probate; a Will does not. A testamentary trust also does not avoid probate.' },
    ],
  },
]
